#!/bin/bash
# PreToolUse hook for Edit and Write: generated files change only by regenerating them.
file_path=$(jq -r '.tool_input.file_path // empty')
relative_path=${file_path#"$CLAUDE_PROJECT_DIR"/}

case "$relative_path" in
  .godot/* | build/* | *.import)
    reason="$relative_path is generated by Godot. Change its source or re-import instead."
    ;;
  art/models/*)
    reason="$relative_path is generated. Change its script in art/scripts/ and rerun it in Blender."
    ;;
  *)
    exit 0
    ;;
esac

jq -n --arg reason "$reason" '{
  hookSpecificOutput: {
    hookEventName: "PreToolUse",
    permissionDecision: "deny",
    permissionDecisionReason: $reason
  }
}'
